oxy_webhelp_navlinks = {"protect_oracle_databases-d39536e38702":{"topics":[{"title":"Backups and archived logs","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> protects Oracle databases using database snapshots and archived log     backups, which run as separate jobs at different frequencies.<\/p>","href":"oracle\/backups_archived_logs.html","attributes":{"data-id":"backups_archived_logs"},"menu":{"hasChildren":false},"tocID":"backups_archived_logs-d39536e38715","next":"backups_archived_logs-d39536e38715"},{"title":"SLA Domain assignments for Oracle objects","shortdesc":"<p class=\"shortdesc\">Assigning an SLA Domain activates automated protection for your Oracle databases.         Direct or inherited SLA Domain assignment enables policy-driven management of database         backups.<\/p>","href":"oracle\/sla_domain_assignments_oracle_objects.html","attributes":{"data-id":"sla_domain_assignments_oracle_objects"},"menu":{"hasChildren":false},"tocID":"sla_domain_assignments_oracle_objects-d39536e38775","topics":[]},{"title":"Assigning protection to Oracle workloads","shortdesc":"<p class=\"shortdesc\">Protect Oracle databases and logs by assigning SLA Domains to Oracle hosts and Oracle         RAC systems. The assigned SLA Domain schedules regular backups of the protected databases         and their associated logs.<\/p>","href":"oracle\/assigning_protection_oracle_workloads.html","attributes":{"data-id":"assigning_protection_oracle_workloads"},"menu":{"hasChildren":false},"tocID":"assigning_protection_oracle_workloads-d39536e38786","topics":[]},{"title":"Database backup customization","shortdesc":"<p class=\"shortdesc\">You can customize the Oracle database backup process to suit your datafile sizes and         rates of change by controlling the number of RMAN channels, multi-section backup settings,         and channel throughput rates.<\/p>","href":"oracle\/database_backup_customization.html","attributes":{"data-id":"database_backup_customization"},"menu":{"hasChildren":false},"tocID":"database_backup_customization-d39536e38797","next":"database_backup_customization-d39536e38797"},{"title":"Multi-node backup for Oracle RAC databases","shortdesc":"<p class=\"shortdesc\">Multi-node backup distributes RMAN backup channels across multiple Oracle RAC nodes,         increasing backup throughput by leveraging the combined network bandwidth and processing         power of the selected nodes.<\/p>","href":"oracle\/multinode_rac_backup.html","attributes":{"data-id":"multinode_rac_backup"},"menu":{"hasChildren":false},"tocID":"multinode_rac_backup-d39536e38830","next":"multinode_rac_backup-d39536e38830"},{"title":"Taking on-demand database backups","shortdesc":"<p class=\"shortdesc\">Manually initiate a database snapshot in addition to policy-based snapshots, and         assign an SLA Domain to manage the on-demand snapshot.<\/p>","href":"oracle\/taking_on_demand_database_backups.html","attributes":{"data-id":"taking_on_demand_database_backups"},"menu":{"hasChildren":false},"tocID":"taking_on_demand_database_backups-d39536e38874","topics":[]},{"title":"Taking on-demand log backups","shortdesc":"<p class=\"shortdesc\">Create an archived redo log backup of a database.<\/p>","href":"oracle\/taking_on_demand_log_backups.html","attributes":{"data-id":"taking_on_demand_log_backups"},"menu":{"hasChildren":false},"tocID":"taking_on_demand_log_backups-d39536e38885","topics":[]},{"title":"Pausing and resuming protection for Oracle databases","shortdesc":"<p class=\"shortdesc\">Pause scheduled backup, archival, and replication actions for         a specific database workload without affecting the protection of other objects managed by         the SLA Domain.<\/p>","href":"oracle\/pausing_resuming_protection_oracle.html","attributes":{"data-id":"pausing_resuming_protection_oracle"},"menu":{"hasChildren":false},"tocID":"pausing_resuming_protection_oracle-d39536e38896","topics":[]}]}};